mkdir -p $TMPDIR/i019 && cat > $TMPDIR/i019/analyze.py << 'PYEOF'
import re, os, json, sys

FREE = re.compile(r'\b(kfree_skb|kfree_skb_reason|consume_skb|dev_kfree_skb_any|napi_consume_skb|__kfree_skb|dev_kfree_skb|skb_unref)\s*\(\s*([^),]*)')
HANDOFF = re.compile(r'\b(skb_queue_tail|sock_queue_rcv_skb|netif_rx|__netif_rx|netif_receive_skb|netif_receive_skb_list|dev_queue_xmit|napi_gro_receive|napi_gro_frags|netif_rx_ni|netif_rx_internal|ieee80211_rx|ieee80211_rx_napi|mac80211...)')

SAVE = re.compile(r'(\w+)\s*=\s*[^=;]*(?:skb->data|skb_headroom\s*\(|skb_tail_pointer\s*\(|\bskb_header_pointer\s*\(|\bskb_copy_bits\b)')
# also: struct field save  foo->bar = ... skb->data
FIELD_SAVE = re.compile(r'([\w.\->]+)\s*=\s*[^=;]*skb->data')

def split_funcs(text):
    funcs = []
    lines = text.split('\n')
    cur = None
    depth = 0
    for i, l in enumerate(lines):
        if cur is None:
            m = re.match(r'^[A-Za-z_][\w\s\*,\(\)\[\]\.#:]*\)\s*$|^[A-Za-z_].*\)\s*\{', l)
            if re.match(r'^(static\s+)?[A-Za-z_][\w\s\*,\(\)\[\]\.#:]*\(', l) and not l.strip().startswith(('if','for','while','switch','return','}')) and not l.strip().endswith(';'):
                cur = {'start': i+1, 'hdr': l, 'lines': [l], 'body_start': None}
                if '{' in l:
                    depth = l.count('{') - l.count('}')
                    cur['body_start'] = i+1
                    if depth <= 0 and l.rstrip().endswith('}'):
                        funcs.append(cur); cur = None
                continue
        else:
            cur['lines'].append(l)
            depth += l.count('{') - l.count('}')
            if cur['body_start'] is None and '{' in l:
                cur['body_start'] = i+1
            if depth <= 0 and '}' in l:
                funcs.append(cur); cur = None
    return funcs, lines

def analyze(path, text):
    results = []
    funcs, all_lines = split_funcs(text)
    for f in funcs:
        ftext = f['lines']
        # find skb-ish params
        params = ' '.join(ftext[:3])
        skbvars = set(re.findall(r'struct sk_buff\s*\*\s*(\w+)', params))
        # saved pointer vars: assigned from skb->data etc.
        saves = []  # (lineno_in_func, var, kind)
        for j, l in enumerate(ftext):
            m = re.search(r'(\w+)\s*=\s*[^=;]*\b' + r'(skb->data|skb_header_pointer|skb_tail_pointer|skb_network_header|skb_transport_header|skb_mac_header|skb_push|skb_put|skb_pull|skb_reserve|__skb_push|__skb_put)\b\s*\(?', l)
            if m:
                var = m.group(1); base = m.group(2)
                # resolve which skb var
                sv = None
                for v in skbvars:
                    if v in l or base in ('skb->data',):
                        sv = v if v in l else (v if 'skb->data' in l and v=='skb' else None)
                saves.append((j, var, base, l.strip()))
        if not saves:
            continue
        # frees/handoffs of any skb var in the func
        frees = []
        for j, l in enumerate(ftext):
            for m in FREE.finditer(l):
                arg = m.group(2).strip()
                for v in skbvars | {'skb'}:
                    if arg == v or arg.startswith(v + '->') or arg.startswith(v + '.') or arg == 'NULL':
                        frees.append((j, m.group(1), arg, l.strip()))
                        break
        if not frees:
            continue
        # uses of saved vars after free
        for (sj, var, base, sline) in saves:
            if var in ('len','lenp','rc','ret','err','nhoff','thoff','offset','size','nr_frags','frags','skb'):
                continue
            for (fj, fn, farg, fline) in frees:
                if fj <= sj:
                    continue
                # look for uses of var between free and end of function
                for k in range(fj+1, len(ftext)):
                    l2 = ftext[k]
                    if re.search(r'\b' + re.escape(var) + r'\b', l2) and '==' not in l2[:l2.find(var)]:
                        results.append({
                            'file': path,
                            'func_start_line': f['start'] + sj,
                            'save_line': f['start'] + sj,
                            'save': sline[:200],
                            'var': var,
                            'free_line': f['start'] + fj,
                            'free': fline[:200],
                            'use_line': f['start'] + k,
                            'use': l2.strip()[:200],
                        })
                        break
                else:
                    continue
                break
    return results

def main():
    base = sys.argv[1]
    out = []
    for root, dirs, files in os.walk(base):
        for fn in files:
            if not fn.endswith('.c'):
                continue
            p = os.path.join(root, fn)
            try:
                t = open(p, errors='replace').read()
            except Exception:
                continue
            if 'skb->data' not in t and 'skb_header_pointer' not in t:
                continue
            out.extend(analyze(p, t))
    json.dump(out, open(os.path.join(os.environ.get('TMPDIR','/tmp'),'i019','candidates.json'),'w'), indent=1)
    print(len(out))

main()
