import re, os, sys

ROOT = "/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/C6/public/snapshots/s03"

FREE_RE = re.compile(r'\b(kfree_skb|consume_skb|dev_kfree_skb_any|dev_kfree_skb_irq|dev_kfree_skb|napi_consume_skb|__kfree_skb|skb_unref)\s*\(')
HANDOFF_RE = re.compile(r'\b(skb_queue_tail|sock_queue_rcv_skb|netif_rx|netif_receive_skb|netif_rx_ni|__netif_rx)\s*\(')

def gather_files():
    for dirpath, dirs, files in os.walk(os.path.join(ROOT, "net")):
        dirs[:] = [d for d in dirs if d not in ("selftests",)]
        for f in files:
            if f.endswith((".c", ".h")):
                yield os.path.join(dirpath, f)

def parse_functions(path):
    """Very rough top-level function splitting for C."""
    with open(path, "r", errors="replace") as fh:
        lines = fh.readlines()
    # find start of each function: line at col 0 that is not '{', '}', '#', comment, and next line ending with '{' or line with ') {' 
    starts = []
    for i, l in enumerate(lines):
        if l.startswith(("{", "}", "#", "/*", "*", "extern", "typedef", "struct", "enum", "union", "EXPORT", "MODULE", "static inline", "#include")):
            continue
        # heuristic: function signature line ends with ')' and next non-empty line starts with '{'
        s = l.rstrip("\n")
        if not s.strip():
            continue
        if i + 1 < len(lines):
            nxt = lines[i+1].lstrip()
            if nxt.startswith("{"):
                starts.append(i)
    starts.append(len(lines))
    for k in range(len(starts)-1):
        a, b = starts[k], starts[k+1]
        body = "".join(lines[a:b])
        yield a, b, lines, body

def strip_comments(text):
    text = re.sub(r'/\*.*?\*/', '', text, flags=re.S)
    text = re.sub(r'//[^\n]*', '', text)
    return text

results = []
for path in gather_files():
    try:
        for a, b, lines, body in parse_functions(path):
            clean = strip_comments(body)
            if not FREE_RE.search(clean) and not HANDOFF_RE.search(clean):
                continue
            flines = clean.split("\n")
            rel = os.path.relpath(path, ROOT)
            # map offsets in flines to original line numbers a+idx approx (comments removed may shift; use body lines with index)
            for idx, ln in enumerate(flines):
                m = FREE_RE.search(ln)
                if m:
                    results.append((rel, a+idx+1, "free", m.group(1), ln.strip()[:120]))
                m = HANDOFF_RE.search(ln)
                if m:
                    results.append((rel, a+idx+1, "handoff", m.group(1), ln.strip()[:120]))
    except Exception as e:
        print("ERR", path, e, file=sys.stderr)

with open(os.path.join(os.environ["TMPDIR"], "i019", "sites.txt"), "w") as out:
    for r in results:
        out.write("%s\t%d\t%s\t%s\t%s\n" % r)
print("total sites:", len(results))
