import re, subprocess, sys, json, os

S = "/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/C6/public/snapshots/s03"
FREE_RE = re.compile(r'\b(kfree_skb|kfree_skb_reason|consume_skb|dev_kfree_skb|dev_kfree_skb_any|dev_kfree_skb_irq|napi_consume_skb|skb_unref|__kfree_skb|netif_rx|netif_receive_skb|netif_rx_ni|netif_rx_any_context|sock_queue_rcv_skb|skb_queue_tail|skb_queue_head|dev_queue_xmit|__dev_queue_xmit)\b')
# Save pattern: identifier = <expr involving ->data or ->head or ->cb or skb_header_pointer or skb_*_header>
SAVE_RE = re.compile(r'^\s*(?:static\s+)?(?:const\s+)?(?:struct\s+)?[A-Za-z_][A-Za-z0-9_]*(?:\s+const)?\s*\**\s*\**([a-z_][a-z0-9_]*)\s*=\s*(?:\([A-Za-z_][A-Za-z0-9_ \*]*\)\s*)?(?:[A-Za-z_][A-Za-z0-9_]*(?:->|\.)|skb_header_pointer\s*\(|skb_(?:network|transport|mac)_header\s*\(|skb_(?:tail|network|transport|mac)_pointer\s*\()', re.I)

results = []
files = subprocess.run(['bash','-c',
  f"grep -rlE '(kfree_skb|consume_skb|dev_kfree_skb|napi_consume_skb|skb_unref|netif_rx|sock_queue_rcv_skb|skb_queue_tail)' {S}/net {S}/drivers/net --include=*.c 2>/dev/null"],
  capture_output=True, text=True).stdout.split()
for f in files:
    rel = f[len(S)+1:]
    try:
        lines = open(f, errors='replace').read().split('\n')
    except Exception:
        continue
    # track saved pointer vars per function; functions delimited by braces at col0
    funcstart = 0
    saved = []  # (var, line_no)
    for i, ln in enumerate(lines):
        if ln and not ln[0].isspace() and ln.rstrip().endswith('{') and '(' in ln and not ln.startswith('#'):
            funcstart = i; saved = []
        m = SAVE_RE.match(ln)
        if m and ('->data' in ln or '->head' in ln or '->cb' in ln or 'skb_header_pointer' in ln or '_header(skb' in ln or '_pointer(skb' in ln or '->frags' in ln):
            saved.append((m.group(1), i+1, ln.strip()))
        if FREE_RE.search(ln):
            for (var, sl, stext) in saved:
                if 0 < i+1 - sl <= 60 and var not in ('skb','dev','sk'):
                    results.append((rel, sl, i+1, var, stext, ln.strip()))
    # end for lines
out = {}
for r in results:
    out.setdefault(f"{r[0]}:{r[1]}", []).append(r)
print(len(results))
with open('candidates.txt','w') as fh:
    for k,v in sorted(out.items()):
        fh.write(k+"\n")
        for r in v:
            fh.write(f"    use? free@{r[2]} var={r[3]} save='{r[4]}' free_line='{r[5]}'\n")
