import os, re, sys

root = "snapshots/s03" if os.path.isdir("snapshots/s03") else "."
trees = ["net", "drivers/net"]
free_pat = re.compile(r'\b(kfree_skb|kfree_skb_reason|__kfree_skb|consume_skb|dev_kfree_skb|dev_kfree_skb_any|dev_kfree_skb_irq|napi_consume_skb|skb_unref)\s*\(')
hand_pat = re.compile(r'\b(skb_queue_tail|skb_queue_head|sock_queue_rcv_skb|sock_queue_err_skb|netif_rx|netif_rx_ni|netif_receive_skb|napi_gro_receive|napi_gro_frags|netif_tx_queue|__netif_rx|ieee80211_rx|dev_queue_xmit)\s*\(')
# derivation lines: local var = ... skb->data ... or = (struct X *)skb->data etc.
deriv_pat = re.compile(r'(\w+)\s*=\s*[^;]*\bskb->data\b')
deriv2 = re.compile(r'(\w+)\s*=\s*\(struct[^)]*\*\)\s*skb_(network|mac|transport)_header\s*\(')

results = []
for tree in trees:
    for dirpath, dirs, files in os.walk(tree):
        for f in files:
            if not f.endswith('.c'):
                continue
            p = os.path.join(dirpath, f)
            try:
                lines = open(p, encoding='utf-8', errors='replace').read().split('\n')
            except Exception:
                continue
            # function extents: track lines starting with '{' or '}' at col 0? use simpler: find func starts via regex of col-0 identifier ( ... )
            func_starts = []  # (start_idx, name)
            for i, l in enumerate(lines):
                m = re.match(r'^(\w[\w\s\*]*?[\w\s\*])\(', ' '.join(l.split()) if False else l)
                if re.match(r'^[A-Za-z_]', l) and '(' in l and not l.startswith(('}', '#', 'struct', 'union', 'enum', 'typedef', 'extern')) or (l.startswith('static') and '(' in l):
                    pass
            # simpler approach: sliding window over whole file
            # save: track derivation events; free/use window
            saves = []  # (line_idx, varname)
            for i, l in enumerate(lines):
                m = deriv_pat.search(l)
                if m:
                    var = m.group(1)
                    if var in ('data',):  # too generic? keep but flag
                        pass
                    saves.append((i, var))
                m2 = deriv2.search(l)
                if m2:
                    saves.append((i, m2.group(1)))
            for (si, var) in saves:
                window = lines[si+1: si+61]
                free_line = None
                use_line = None
                for j, wl in enumerate(window):
                    if free_line is None and (free_pat.search(wl) or hand_pat.search(wl)):
                        free_line = (si+1+j, wl.strip())
                    if use_line is None and free_line is not None and re.search(r'\b' + re.escape(var) + r'\b', wl) and not re.search(r'\b' + re.escape(var) + r'\s*=', wl):
                        use_line = (si+1+j, wl.strip())
                        break
                if free_line and use_line:
                    results.append((p, si+1, var, free_line, use_line))

for r in results:
    print(f"{r[0]}:{r[1]} var={r[2]} free@{r[3][0]}:{r[3][1][:90]} use@{r[4][0]}:{r[4][1][:90]}")
print("TOTAL", len(results), file=sys.stderr)
PYEOF
