		can_free_echo_skb(dev, can_tx_msg->putidx, NULL);
		virtio_can_free_tx_idx(priv, can_tx_msg->putidx);
		netif_stop_queue(dev);
		kfree(can_tx_msg);
		dev->stats.tx_dropped++;
